(*
  Statement-only formalization of Thousand Theorems corpus artifact Q1008566
  (thousand-theorems__hol-light__Q1008566), "Gauss–Lucas theorem": the
  critical points of a nonconstant complex polynomial lie in the convex hull
  of its roots, together with the explicit root-multiplicity-weighted
  center-of-mass identity. This file contains no proof.
*)

let cpoly_output = open_out "/dev/null";;
let cpoly_formatter = Format.formatter_of_out_channel cpoly_output;;
let previous_file_loader = !Hol_loader.file_loader;;
Hol_loader.file_loader :=
  (fun path -> Toploop.use_file cpoly_formatter path);;
let cpoly_loaded =
  Toploop.use_file cpoly_formatter "Complex/cpoly.ml";;
Hol_loader.file_loader := previous_file_loader;;
Format.pp_print_flush cpoly_formatter ();;
close_out cpoly_output;;
if not cpoly_loaded then failwith "failed to load Complex/cpoly.ml";;

let Polynomial_eq_centerMass_of_eval_derivative_eq_zero =
  `let root_set =
     \p:complex list. {w:complex | poly p w = Cx(&0)} in
   let deriv_root_weight =
     \(p:complex list) (z:complex) (w:complex).
       if poly p z = Cx(&0) then
         if w = z then &1 else &0
       else
         &(order w p) / (norm(z - w) pow 2) in
   let complex_sum =
     \(s:complex->bool) (f:complex->complex).
       iterate ((+):complex->complex->complex) s f in
   let center_mass =
     \(s:complex->bool) (weight:complex->real).
       Cx(inv(sum s weight)) *
       complex_sum s (\w:complex. Cx(weight w) * w) in
   !p:complex list. !z:complex.
     0 < degree p /\
     poly (poly_diff p) z = Cx(&0)
     ==>
     z = center_mass (root_set p) (deriv_root_weight p z)`;;

let Polynomial_rootSet_derivative_subset_convexHull_rootSet =
  `let root_set =
     \p:complex list. {w:complex | poly p w = Cx(&0)} in
   let complex_convex =
     \(t:complex->bool).
       !x y:complex. !u v:real.
         x IN t /\ y IN t /\
         &0 <= u /\ &0 <= v /\ u + v = &1
         ==> Cx(u) * x + Cx(v) * y IN t in
   let complex_convex_hull =
     \(s:complex->bool).
       {z:complex |
          !t:complex->bool.
            s SUBSET t /\ complex_convex t ==> z IN t} in
   !p:complex list.
     0 < degree p
     ==>
     root_set (poly_diff p) SUBSET
     complex_convex_hull (root_set p)`;;

:: Statement-only formalization of thousand-theorems corpus artifact Q1033910,
:: "Cantor–Bernstein–Schroeder theorem": injections between two arbitrary sets
:: in both directions imply a bijection between them. This file contains no
:: proof.

environ
  vocabularies TARSKI, XBOOLE_0, SUBSET_1, RELAT_1, FUNCT_1, FUNCT_2;
  notations TARSKI, XBOOLE_0, SUBSET_1, RELAT_1, FUNCT_1, RELSET_1,
    FUNCT_2;
  constructors RELSET_1, FUNCT_2;
  registrations XBOOLE_0, SUBSET_1, RELAT_1, FUNCT_1, RELSET_1, FUNCT_2;
  requirements BOOLE, SUBSET;

begin

::$P-
theorem
  for A,B being set,
      f,g being Function st
    dom f = A & rng f c= B & f is one-to-one &
    dom g = B & rng g c= A & g is one-to-one
  holds ex h being Function st
    dom h = A & rng h = B & h is one-to-one
proof
end;
::$P+

:: Statement-only formalization of thousand-theorems corpus artifact Q1050203,
:: "Cantor's intersection theorem": the intersection of a nonempty
:: downward-directed family of nonempty compact closed subsets of an
:: arbitrary topological space is nonempty. This file contains no proof.

environ
  vocabularies TARSKI, XBOOLE_0, SUBSET_1, SETFAM_1, STRUCT_0, PRE_TOPC,
    TOPS_2, COMPTS_1, RCOMP_1;
  notations TARSKI, XBOOLE_0, SUBSET_1, SETFAM_1, STRUCT_0, PRE_TOPC,
    TOPS_2, COMPTS_1;
  constructors SETFAM_1, TOPS_2, COMPTS_1;
  registrations XBOOLE_0, SUBSET_1, STRUCT_0, PRE_TOPC, TOPS_1, COMPTS_1;
  requirements SUBSET, BOOLE;
  definitions TARSKI;
  expansions TARSKI;

begin

::$P-
theorem
  for T being TopSpace,
      S being non empty Subset-Family of T st
    (for U,V being Subset of T st U in S & V in S
      holds ex W being Subset of T st
        W in S & W c= U & W c= V) &
    (for U being Subset of T st U in S holds
      (U <> {}) & (U is compact) & (U is closed))
  holds meet S <> {}
proof
end;
::$P+

(*
  Statement-only formalization of Thousand Theorems corpus artifact Q1057919,
  "Sylow theorems": existence of subgroups of prescribed prime-power order,
  conjugacy of Sylow p-subgroups, divisibility of their count by subgroup
  index, and congruence of that count to one modulo p. This file contains no
  proof.
*)

let sylow_output = open_out "/dev/null";;
let sylow_formatter = Format.formatter_of_out_channel sylow_output;;
let previous_file_loader = !Hol_loader.file_loader;;
Hol_loader.file_loader :=
  (fun path -> Toploop.use_file sylow_formatter path);;
let sylow_library_loaded =
  Toploop.use_file sylow_formatter "Library/grouptheory.ml";;
Hol_loader.file_loader := previous_file_loader;;
Format.pp_print_flush sylow_formatter ();;
close_out sylow_output;;
if not sylow_library_loaded then
  failwith "failed to load Library/grouptheory.ml";;

let SYLOW_EXISTS_SUBGROUP_CARD_POW_PRIME =
  `!G:A group. !p n:num.
     FINITE (group_carrier G) /\
     prime p /\
     p EXP n divides CARD (group_carrier G)
     ==> ?K:A->bool.
           K subgroup_of G /\
           CARD K = p EXP n`;;

let SYLOW_IS_PRETRANSITIVE_OF_FINITE =
  `let is_p_subgroup =
     \(G:A group) (p:num) (H:A->bool).
       H subgroup_of G /\
       pgroup {p} (subgroup_generated G H) in
   let is_sylow =
     \(G:A group) (p:num) (P:A->bool).
       is_p_subgroup G p P /\
       !Q:A->bool.
         is_p_subgroup G p Q /\ P SUBSET Q ==> Q = P in
   !G:A group. !p:num.
     prime p /\
     FINITE {P:A->bool | is_sylow G p P}
     ==> !P Q:A->bool.
           is_sylow G p P /\
           is_sylow G p Q
           ==> group_conjugate G P Q`;;

let SYLOW_CARD_DVD_INDEX =
  `let is_p_subgroup =
     \(G:A group) (p:num) (H:A->bool).
       H subgroup_of G /\
       pgroup {p} (subgroup_generated G H) in
   let is_sylow =
     \(G:A group) (p:num) (P:A->bool).
       is_p_subgroup G p P /\
       !Q:A->bool.
         is_p_subgroup G p Q /\ P SUBSET Q ==> Q = P in
   let subgroup_index =
     \(G:A group) (P:A->bool).
       let cosets =
         {left_coset G x P | x | x IN group_carrier G} in
       if FINITE cosets then CARD cosets else 0 in
   !G:A group. !p:num. !P:A->bool.
     prime p /\
     FINITE {Q:A->bool | is_sylow G p Q} /\
     is_sylow G p P
     ==> CARD {Q:A->bool | is_sylow G p Q}
         divides subgroup_index G P`;;

let CARD_SYLOW_MODEQ_ONE =
  `let is_p_subgroup =
     \(G:A group) (p:num) (H:A->bool).
       H subgroup_of G /\
       pgroup {p} (subgroup_generated G H) in
   let is_sylow =
     \(G:A group) (p:num) (P:A->bool).
       is_p_subgroup G p P /\
       !Q:A->bool.
         is_p_subgroup G p Q /\ P SUBSET Q ==> Q = P in
   !G:A group. !p:num.
     prime p /\
     FINITE {P:A->bool | is_sylow G p P}
     ==> (CARD {P:A->bool | is_sylow G p P} == 1) (mod p)`;;

(*
  Statement-only formalization of Thousand Theorems corpus artifact Q1065966,
  "Isomorphism theorem": the first, second, and third isomorphism theorems for
  quotient groups. This file contains no proof.
*)

let isomorphism_theorem_output = open_out "/dev/null";;
let isomorphism_theorem_formatter =
  Format.formatter_of_out_channel isomorphism_theorem_output;;
let previous_file_loader = !Hol_loader.file_loader;;
let previous_verbose = !verbose;;
let previous_type_invention_warning = !type_invention_warning;;
verbose := false;;
type_invention_warning := false;;
Hol_loader.file_loader :=
  (fun path -> Toploop.use_file isomorphism_theorem_formatter path);;
let isomorphism_theorem_library_loaded =
  Toploop.use_file isomorphism_theorem_formatter "Library/grouptheory.ml";;
Hol_loader.file_loader := previous_file_loader;;
verbose := previous_verbose;;
type_invention_warning := previous_type_invention_warning;;
Format.pp_print_flush isomorphism_theorem_formatter ();;
close_out isomorphism_theorem_output;;
if not isomorphism_theorem_library_loaded then
  failwith "failed to load Library/grouptheory.ml";;

let QUOTIENT_GROUP_QUOTIENT_KER_EQUIV_RANGE =
  `!G H (f:A->B).
     group_homomorphism (G,H) f
     ==> quotient_group G (group_kernel (G,H) f) isomorphic_group
         subgroup_generated H (group_image (G,H) f)`;;

let QUOTIENT_GROUP_QUOTIENT_INF_EQUIV_PROD_NORMAL_QUOTIENT =
  `!G (H:A->bool) N.
     H subgroup_of G /\
     N normal_subgroup_of G
     ==> quotient_group (subgroup_generated G H) (H INTER N)
         isomorphic_group
         quotient_group
           (subgroup_generated G (group_setmul G H N)) N`;;

let QUOTIENT_GROUP_QUOTIENT_QUOTIENT_EQUIV_QUOTIENT =
  `!G (N:A->bool) M.
     N normal_subgroup_of G /\
     M normal_subgroup_of G /\
     N SUBSET M
     ==> quotient_group
           (quotient_group G N)
           (IMAGE (right_coset G N) M)
         isomorphic_group
         quotient_group G M`;;

